import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { Form, Button, Col, Row, Alert, Spinner } from "react-bootstrap";
import axios from "axios";
import AddIngredient from "../AddIngredient/AddIngredient";
import "./EditRecipe.css";

const baseURL = "http://localhost:8080/api/recipes";

function EditRecipe() {
  const { recipeId } = useParams();
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    id: null,
    name: "",
    description: "",
    imageUrl: "",
    ingredients: [],
  });

  const [listId, setListId] = useState(1);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [status, setStatus] = useState(null);

  useEffect(() => {
    const loadRecipe = async () => {
      setLoading(true);
      setStatus(null);
      try {
        const response = await axios.get(`${baseURL}/recipe/${recipeId}`);
        const data = response.data;
        const mappedIngredients = (data.ingredients || []).map((ingredient, index) => ({
          listId: index + 1,
          id: ingredient.id || null,
          name: ingredient.name || "",
          comment: ingredient.comment || "",
          unit: ingredient.unit || "PIECE",
          amount: ingredient.amount ?? "",
        }));
        setFormData({
          id: data.id,
          name: data.name || "",
          description: data.description || "",
          imageUrl: data.imageUrl || "",
          ingredients: mappedIngredients,
        });
        setListId(mappedIngredients.length + 1);
      } catch (error) {
        setStatus({ type: "error", message: "Recipe konnte nicht geladen werden." });
      } finally {
        setLoading(false);
      }
    };

    loadRecipe();
  }, [recipeId]);

  const handleFieldChange = (field) => (e) => {
    setFormData({ ...formData, [field]: e.target.value });
  };

  const addIngredient = () => {
    setFormData({
      ...formData,
      ingredients: [
        ...formData.ingredients,
        { listId, id: null, name: "", comment: "", unit: "PIECE", amount: "" },
      ],
    });
    setListId(listId + 1);
  };

  const updateIngredient = (updatedIngredient) => {
    const updatedIngredients = formData.ingredients.map((ingredient) =>
      ingredient.listId === updatedIngredient.listId ? updatedIngredient : ingredient
    );
    setFormData({ ...formData, ingredients: updatedIngredients });
  };

  const removeIngredient = (ingredientListId) => {
    const updatedIngredients = formData.ingredients.filter(
      (ingredient) => ingredient.listId !== ingredientListId
    );
    setFormData({ ...formData, ingredients: updatedIngredients });
  };

  const canSubmit =
    formData.name.trim() &&
    formData.description.trim() &&
    formData.imageUrl.trim() &&
    formData.ingredients.length > 0 &&
    formData.ingredients.every(
      (ingredient) => ingredient.name.trim() && ingredient.amount !== ""
    );

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!canSubmit || submitting) {
      return;
    }

    setSubmitting(true);
    setStatus(null);

    const payload = {
      id: formData.id,
      name: formData.name.trim(),
      description: formData.description.trim(),
      imageUrl: formData.imageUrl.trim(),
      ingredients: formData.ingredients.map(({ id, name, comment, unit, amount }) => ({
        id: id || null,
        name: name.trim(),
        comment: (comment || "").trim(),
        unit,
        amount: Number(amount),
      })),
    };

    try {
      await axios.put(`${baseURL}/${recipeId}`, payload);
      setStatus({ type: "success", message: "Recipe wurde aktualisiert." });
      navigate("/");
    } catch (error) {
      setStatus({ type: "error", message: "Aktualisierung fehlgeschlagen." });
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className='bg m-3'>
        <Spinner
          animation='border'
          role='status'
        />
        <span className='ms-2'>Lade Recipe...</span>
      </div>
    );
  }

  return (
    <div className='bg'>
      <div className='m-3'>
        <h1 className='h3 bg-dark text-bg-primary mt-2'>Edit Recipe</h1>

        {status && (
          <Alert variant={status.type === "success" ? "success" : "danger"}>
            {status.message}
          </Alert>
        )}

        <Form onSubmit={handleSubmit}>
          <Form.Group
            className='mb-3'
            controlId='editRecipeName'>
            <Form.Label>Recipe Name:</Form.Label>
            <Form.Control
              placeholder='Name'
              value={formData.name}
              onChange={handleFieldChange("name")}
              required
            />
          </Form.Group>

          <Form.Group
            className='mb-3'
            controlId='editRecipeDescription'>
            <Form.Label>Description:</Form.Label>
            <Form.Control
              placeholder='Description'
              value={formData.description}
              onChange={handleFieldChange("description")}
              required
            />
          </Form.Group>

          <Form.Group
            className='mb-4'
            controlId='editRecipeImageUrl'>
            <Form.Label>Image URL:</Form.Label>
            <Form.Control
              placeholder='URL'
              value={formData.imageUrl}
              onChange={handleFieldChange("imageUrl")}
              required
            />
          </Form.Group>

          <Row className='fw-semibold'>
            <Col>Ingredient</Col>
            <Col>Unit</Col>
            <Col>Amount</Col>
            <Col>Note</Col>
            <Col xs={1}></Col>
          </Row>
          <hr />

          {formData.ingredients.length === 0 && (
            <p className='text-muted'>Fuege mindestens eine Zutat hinzu.</p>
          )}

          {formData.ingredients.map((ingredient) => (
            <AddIngredient
              key={ingredient.listId}
              ingredient={ingredient}
              onChange={updateIngredient}
              onRemove={removeIngredient}
            />
          ))}

          <Row className='mt-3'>
            <Col>
              <Button
                variant='warning'
                onClick={addIngredient}
                className='mt-1'>
                Add Ingredient
              </Button>
            </Col>
          </Row>

          <Button
            variant='primary'
            type='submit'
            className='my-4'
            disabled={!canSubmit || submitting}>
            {submitting ? "Saving..." : "Update Recipe"}
          </Button>
        </Form>
      </div>
    </div>
  );
}

export default EditRecipe;
